import React, { useState } from "react";
import ChartistGraph from "react-chartist";
import { Card, Container, Row, Col, Form, Button } from "react-bootstrap";

function History() {
  // --- 1. เตรียมข้อมูลสำหรับตัวเลือกแบบไทย ---
  const days = Array.from({ length: 31 }, (_, i) => i + 1);
  const monthsThai = [
    "มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน",
    "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"
  ];
  const currentYearBE = new Date().getFullYear() + 543;
  const yearsBE = [currentYearBE - 1, currentYearBE, currentYearBE + 1];
  const hours = Array.from({ length: 24 }, (_, i) => i.toString().padStart(2, '0'));
  const minutes = ["00", "15", "30", "45"];

  // --- 2. State สำหรับเก็บค่าที่เลือก ---
  const [day, setDay] = useState("1");
  const [month, setMonth] = useState("1"); // 1 = มกราคม
  const [yearBE, setYearBE] = useState(currentYearBE.toString());
  const [startH, setStartH] = useState("07");
  const [startM, setStartM] = useState("00");
  const [endH, setEndH] = useState("22");
  const [endM, setEndM] = useState("00");
  
  const [cameraId, setCameraId] = useState("CAM01");
  const [data, setData] = useState({ labels: [], series: [] });

  // --- 3. ฟังก์ชันดึงข้อมูล (แปลง พ.ศ. กลับเป็น ค.ศ. ส่งให้ API) ---
  const fetchHistory = async () => {
    const yearCE = parseInt(yearBE) - 543;
    const formattedDate = `${yearCE}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
    const startTime = `${startH}:${startM}`;
    const endTime = `${endH}:${endM}`;

    try {
      const response = await fetch(
        `http://localhost:3000/api/history?cameraId=${cameraId}&date=${formattedDate}&startTime=${startTime}&endTime=${endTime}`
      );
      const result = await response.json();
      
      // ใส่ "น." ต่อท้ายเวลาบนกราฟให้คนไทยอ่านง่าย
      const thaiLabels = result.labels.map(label => label + " น.");
      setData({ labels: thaiLabels, series: result.series });
    } catch (err) {
      console.error("Error:", err);
    }
  };

  return (
    <Container fluid>
      <Row>
        <Col md="12">
          <Card>
            <Card.Header>
              <Card.Title as="h4">เลือกประวัติการเดินทาง (รูปแบบไทย 24 ชม.)</Card.Title>
            </Card.Header>
            <Card.Body>
              <Row>
                <Col md="12"><label>วันที่ต้องการตรวจสอบ</label></Col>
                <Col md="2">
                  <Form.Control as="select" value={day} onChange={(e) => setDay(e.target.value)}>
                    {days.map(d => <option key={d} value={d}>{d}</option>)}
                  </Form.Control>
                </Col>
                <Col md="3">
                  <Form.Control as="select" value={month} onChange={(e) => setMonth(e.target.value)}>
                    {monthsThai.map((m, i) => <option key={m} value={i + 1}>{m}</option>)}
                  </Form.Control>
                </Col>
                <Col md="2">
                  <Form.Control as="select" value={yearBE} onChange={(e) => setYearBE(e.target.value)}>
                    {yearsBE.map(y => <option key={y} value={y}>{y}</option>)}
                  </Form.Control>
                </Col>
                <Col md="5">
                  <Form.Control as="select" value={cameraId} onChange={(e) => setCameraId(e.target.value)}>
                    <option value="CAM01">วิศวะ (CAM01)</option>
                    <option value="CAM02">วิทยาศาสตร์ (CAM02)</option>
                    <option value="CAM03">ศิลปศาสตร์ (CAM03)</option>
                    <option value="CAM04">PKY (CAM04)</option>
                  </Form.Control>
                </Col>
              </Row>

              <Row className="mt-3">
                <Col md="12"><label>ช่วงเวลา (น.)</label></Col>
                <Col md="2">
                  <Form.Control as="select" value={startH} onChange={(e) => setStartH(e.target.value)}>
                    {hours.map(h => <option key={h} value={h}>{h} น.</option>)}
                  </Form.Control>
                </Col>
                <Col md="2">
                  <Form.Control as="select" value={startM} onChange={(e) => setStartM(e.target.value)}>
                    {minutes.map(m => <option key={m} value={m}>{m}</option>)}
                  </Form.Control>
                </Col>
                <Col md="1" className="text-center align-self-center">ถึง</Col>
                <Col md="2">
                  <Form.Control as="select" value={endH} onChange={(e) => setEndH(e.target.value)}>
                    {hours.map(h => <option key={h} value={h}>{h} น.</option>)}
                  </Form.Control>
                </Col>
                <Col md="2">
                  <Form.Control as="select" value={endM} onChange={(e) => setEndM(e.target.value)}>
                    {minutes.map(m => <option key={m} value={m}>{m}</option>)}
                  </Form.Control>
                </Col>
                <Col md="3">
                  <Button className="btn-fill w-100" variant="primary" onClick={fetchHistory}>ค้นหาข้อมูล</Button>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* --- ส่วนแสดงผลกราฟ --- */}
      {data.labels.length > 0 && (
        <Row>
          <Col md="12">
            <Card>
              <Card.Header>
                <Card.Title as="h4">สถิติ {cameraId} วันที่ {day} {monthsThai[month-1]} {yearBE}</Card.Title>
                <p className="card-category">เวลา {startH}:{startM} น. - {endH}:{endM} น.</p>
              </Card.Header>
              <Card.Body>
                <ChartistGraph
                  data={data}
                  type="Line"
                  options={{
                    low: 0,
                    height: "300px",
                    showArea: true,
                    fullWidth: true,
                    axisX: { showGrid: false }
                  }}
                />
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}
    </Container>
  );
}

export default History;
